catalog_script_client.script:
function onLoad() {

    var status = g_form.getValue("current_status");
	var editable_flag = g_form.getValue("editable_flag");
	alert(editable_flag);
    if (status == "1" || status == "2" || status == "7" || status == "8" ) {
        g_form.setValue("editable_flag", yes);
    } else {
        g_form.setValue("editable_flag", no);
    }
}
